    Examples
    --------

    >>> a = pybamm.Symbol('a')
    >>> b = pybamm.Symbol('b')
    >>> for node in (a*b).pre_order():
    ...     print(node.name)
    *
    a
    b
    """
    anytree = import_optional_dependency("anytree")
    return anytree.PreOrderIter(self)

